from copy import deepcopy


class AllocationLedger:
    def __init__(self, starting_number=1):
        if isinstance(starting_number, bool) or not isinstance(starting_number, int) or starting_number < 1:
            raise ValueError("starting_number must be a positive integer")
        self._next_number = starting_number
        self._records = {}
        self._order = []

    def reserve(self, resource, member, scheduled_label=None, metadata=None):
        if not isinstance(resource, str) or not resource:
            raise ValueError("resource must be a non-empty string")
        if not isinstance(member, str) or not member:
            raise ValueError("member must be a non-empty string")
        if scheduled_label is not None and not isinstance(scheduled_label, str):
            raise TypeError("scheduled_label must be a string or None")
        if metadata is not None and not isinstance(metadata, dict):
            raise TypeError("metadata must be a dictionary or None")

        allocation_id = f"A{self._next_number:04d}"
        self._next_number += 1
        record = {
            "id": allocation_id,
            "resource": resource,
            "member": member,
            "scheduled_label": scheduled_label,
            "status": 0,
            "metadata": deepcopy(metadata) if metadata is not None else {},
        }
        self._records[allocation_id] = record
        self._order.append(allocation_id)
        return deepcopy(record)

    def get(self, allocation_id):
        if allocation_id not in self._records:
            raise KeyError(allocation_id)
        return deepcopy(self._records[allocation_id])

    def all_allocations(self):
        return [dict(self._records[item_id]) for item_id in self._order]

